std::vector<MaterialAidRemaining>remaining(const MaterialAidReadContext&x,const MaterialAidObligation&o,const WorldMoment*through,const SourceRef*actual_close_cut){const auto cut=actual_close_cut?std::optional<std::size_t>{header(x.common,*actual_close_cut)}:std::nullopt;const auto&c=commitment(x,o.schedule_commitment_id);const auto t=terms(x,schedule(x,c.schedule_id));auto out=original_measures(*t.original_term);
 for(const auto&id:o.issue_result_refs){const auto*r=x.state.resource_issues.find(id);if(!r||r->id!=id)fail("MaterialAidIssueResultRequired",id);const auto a=issue(x,o,*r);auto m=std::find_if(out.begin(),out.end(),[&](const auto&v){return same(v.unit,a.unit);});if(m==out.end())fail("MaterialAidUnpromisedIssue",id);m->issued=add(m->issued,a.quantity);if(m->issued>m->promised)fail("MaterialAidIssueExceedsPromise",id);Integer received=0;for(const auto&rid:o.receipt_result_refs){const auto*rr=x.state.receipts.find(rid);if(!rr)fail("MaterialAidReceiptResultRequired",rid);if(rr->issue_result_id==id){const auto actual=receipt(x,o,*rr);received=add(received,actual.quantity);}}if(received>a.quantity)fail("MaterialAidReceiptExceedsActualIssue",id);}
 for(const auto&id:o.receipt_result_refs){const auto*r=x.state.receipts.find(id);if(!r||r->id!=id||std::count(o.issue_result_refs.begin(),o.issue_result_refs.end(),r->issue_result_id)!=1)fail("MaterialAidReceiptResultRequired",id);const auto a=receipt(x,o,*r);if(through&&compare(a.occurred_at,*through)>0)continue;
 // A real receiving adoption appended after this actual close, including at
 // the same M, cannot retrospectively erase the already applied late result.
 // Hot close passes no cut and consumes only its currently applied prefix.
 if(cut&&header(x.common,material_aid_receipt_source(r->id))>=*cut)continue;auto m=std::find_if(out.begin(),out.end(),[&](const auto&v){return same(v.unit,a.unit);});if(m==out.end())fail("MaterialAidUnpromisedReceipt",id);m->received=add(m->received,a.quantity);if(m->received>m->promised)fail("MaterialAidReceiptExceedsPromise",id);}
 for(auto&m:out)m.remaining=m.promised-m.received;return out;}
MaterialAidObligationState projected_state(const MaterialAidObligation&o,const std::vector<MaterialAidRemaining>&r){bool all=true,any=false;for(const auto&m:r){all&=m.remaining==0;any|=m.received>0;}if(all)return MaterialAidObligationState::received;if(o.deadline_result_ref)return MaterialAidObligationState::late;return any?MaterialAidObligationState::partly_received:MaterialAidObligationState::owed;}
void validate_established_terms(const MaterialAidReadContext&x,const MaterialAidObligation&o){const auto&c=commitment(x,o.schedule_commitment_id);validate_commitment_holds(x,c);const auto&s=schedule(x,c.schedule_id);const auto t=terms(x,s);if(o.occurrence.ordinal<0||static_cast<std::uint64_t>(o.occurrence.ordinal)>=c.established_occurrence_refs.size()||!same_aid_occurrence(o.occurrence,key(s,o.occurrence.ordinal)))fail("MaterialAidOccurrenceIdentityMismatch",o.id);const auto&e=establishment(x,c.established_occurrence_refs[static_cast<std::size_t>(o.occurrence.ordinal)]);if(e.schedule_commitment_id!=c.id||e.occurrence_ordinal!=o.occurrence.ordinal||e.original_obligation_ref.owner_domain!="local_economy"||e.original_obligation_ref.obligation_id!=o.id||compare(e.established_at,o.established_at))fail("MaterialAidEstablishmentObligationMismatch",o.id);before(x.common,aid_schedule_commitment_source(c.id),material_aid_establishment_source(e.id));const auto due=take(material_aid_occurrence_due(*t.original_term,o.occurrence.ordinal));if(o.due_tick!=due||o.delivery_deadline_tick!=add(due,t.original_term->delivery_deadline_ticks)||compare(o.established_at,WorldMoment{due,{}})||compare(o.established_at,now(x))>0||due>=t.original_terms->effective_window.until_tick||(t.terminated_at&&compare(o.established_at,*t.terminated_at)>=0)||!same(o.beneficiary,t.original_term->beneficiary)||!same_source_ref(o.delivery_site,t.original_term->delivery_site)||!same(o.resource_acceptance_ref,c.resource_acceptance_ref))fail("MaterialAidOriginalDebtTermsMismatch",o.id);
 const auto items=normalized_items(*t.original_term);if(o.frozen_items.size()!=items.size()||bool(o.frozen_money)!=bool(t.original_term->money))fail("MaterialAidFrozenMeasureMismatch",o.id);for(std::size_t i=0;i<items.size();++i)if(o.frozen_items[i].item_id!=items[i].item_id||o.frozen_items[i].quantity!=items[i].quantity)fail("MaterialAidFrozenItemMismatch",o.id);if(o.frozen_money&&(o.frozen_money->currency_id!=t.original_term->money->currency_id||o.frozen_money->amount!=t.original_term->money->amount))fail("MaterialAidFrozenMoneyMismatch",o.id);
 const auto resources=accepted_resources(x,c);if(o.item_routes.size()!=resources.item_routes.size()||bool(o.money_route)!=bool(resources.money_route))fail("MaterialAidFrozenContainerMismatch",o.id);for(std::size_t i=0;i<o.item_routes.size();++i){const auto&a=o.item_routes[i];const auto&b=resources.item_routes[i];if(a.item_id!=b.item_id||a.source_inventory_id!=b.source_inventory_id||a.beneficiary_inventory_id!=b.beneficiary_inventory_id)fail("MaterialAidFrozenContainerMismatch",o.id);}if(o.money_route&&(o.money_route->source_wallet_id!=resources.money_route->source_wallet_id||o.money_route->beneficiary_wallet_id!=resources.money_route->beneficiary_wallet_id))fail("MaterialAidFrozenWalletMismatch",o.id);
 const auto measures=original_measures(*t.original_term);if(e.converted_reservation_refs.size()!=measures.size())fail("MaterialAidConversionCoverageMismatch",e.id);for(std::size_t i=0;i<measures.size();++i){const auto*h=x.state.occurrence_cap_reservations.find(e.converted_reservation_refs[i]);if(!h||h->occurrence_ordinal!=o.occurrence.ordinal||h->schedule_commitment_id!=c.id||!same(h->unit,measures[i].unit)||h->quantity!=measures[i].promised||!h->establishment_result_ref||!same_source_ref(*h->establishment_result_ref,material_aid_establishment_source(e.id))||h->release_result_ref)fail("MaterialAidConversionAmountMismatch",e.id);}
 for(std::size_t i=0;i<o.issue_result_refs.size();++i)for(std::size_t j=0;j<i;++j)if(o.issue_result_refs[i]==o.issue_result_refs[j])fail("DuplicateMaterialAidIssue",o.id);for(std::size_t i=0;i<o.receipt_result_refs.size();++i)for(std::size_t j=0;j<i;++j)if(o.receipt_result_refs[i]==o.receipt_result_refs[j])fail("DuplicateMaterialAidReceipt",o.id);
 if(bool(o.original_money_obligation_id)!=bool(o.frozen_money)||bool(o.original_money_arrear_id)!=bool(o.frozen_money))fail("MaterialAidOriginalMoneyPayableCoverageMismatch",o.id);
}
namespace {
enum class ObligationReadUse { complete, original_budget_evidence };
void validate_obligation_impl(const MaterialAidReadContext&x,const MaterialAidObligation&o,ObligationReadUse use){
 validate_established_terms(x,o);
 if(o.frozen_money){
  const auto*context=take(service_finance::original_obligation_read(x.common,x.economy,x.obligations));
  const SourceRef due{"local_economy","contract_payment_due",*o.original_money_arrear_id};
  const auto money=take(use==ObligationReadUse::complete?read_economic_payable(*context,due):read_economic_payable_for_budget_evidence(*context,due));
  // Every original money-receiving leg references exactly one already recorded
  // cash payment for this original debt. Intermediate issue/receipt adoptions
  // may be incomplete only inside the actual event transaction; whole Aid
  // publication separately requires complete original receiving coverage.
  const auto originals=take(x.resources.enumerate_actual_aid_receipts(o.occurrence));std::size_t receiving_count=0;Integer received=0;
  for(std::size_t i=0;i<originals.size();++i){const auto actual=original_receipt(x,o,originals[i]);if(!std::holds_alternative<BudgetMoneyQian>(actual.unit))continue;
   const auto cash=take(read_material_aid_actual_cash_payment(x,{"local_economy",o.id},originals[i]));
   for(std::size_t j=0;j<i;++j){const auto prior=original_receipt(x,o,originals[j]);if(!std::holds_alternative<BudgetMoneyQian>(prior.unit))continue;const auto prior_cash=take(read_material_aid_actual_cash_payment(x,{"local_economy",o.id},originals[j]));if(prior_cash.payment==cash.payment)fail("MaterialAidCashReceiptReused",cash.payment->id);}
   ++receiving_count;received=add(received,cash.payment->amount);
  }
  // Each mapped cash pointer belongs to this arrear. Equal cardinality plus
  // unique pointers proves complete reverse coverage without copying IDs.
  std::size_t count=0;for(const auto&p:x.economy.payments.rows())if(p.second.arrear_id==due.id)++count;
  if(count!=receiving_count||received!=money.cash_paid||money.positive_increments||money.unpaid_void)fail("MaterialAidOriginalMoneyPaidCoverageMismatch",o.id);
 }
 if(o.state!=projected_state(o,remaining(x,o)))fail("MaterialAidRemainingStateMismatch",o.id);
 if(o.deadline_result_ref){const auto*d=x.state.deadline_results.find(*o.deadline_result_ref);const WorldMoment deadline{o.delivery_deadline_tick,{}};if(!d||d->id!=*o.deadline_result_ref||d->obligation_id!=o.id||compare(d->occurred_at,deadline)||compare(deadline,now(x))>0)fail("MaterialAidDeadlineResultMismatch",o.id);const auto&c=commitment(x,o.schedule_commitment_id);const auto&cut=c.established_occurrence_refs[static_cast<std::size_t>(o.occurrence.ordinal)];before(x.common,cut,material_aid_deadline_source(d->id));const auto close_cut=material_aid_deadline_source(d->id);bool unpaid=false;for(const auto&m:remaining(x,o,&deadline,&close_cut))unpaid|=m.remaining>0;if(!unpaid)fail("MaterialAidFalseLateResult",d->id);const auto t=terms(x,schedule(x,c.schedule_id));if(const auto*p=std::get_if<TreatyBoundedCompensation>(&t.original_term->late_policy)){if(p->maximum_amount==0){if(d->compensation_obligation_ref)fail("MaterialAidZeroCompensationCannotCreateDebt",d->id);}else{if(p->maximum_amount<0||!d->compensation_obligation_ref)fail("MaterialAidCompensationSourceRequired",d->id);if(d->compensation_obligation_ref->owner_domain=="local_economy"&&d->compensation_obligation_ref->obligation_id==o.id)fail("MaterialAidCompensationCannotBeOriginalDebt",o.id);take(use==ObligationReadUse::complete?x.resources.validate_aid_compensation(o,*p,*d->compensation_obligation_ref,deadline):x.resources.validate_aid_compensation_for_budget_evidence(o,*p,*d->compensation_obligation_ref,deadline));}}else if(d->compensation_obligation_ref)fail("MaterialAidUnexpectedCompensation",d->id);}
}
} // one original validation algorithm; named budget cut avoids authority recursion
void validate_obligation(const MaterialAidReadContext&x,const MaterialAidObligation&o){validate_obligation_impl(x,o,ObligationReadUse::complete);}
void validate_obligation_for_budget_evidence(const MaterialAidReadContext&x,const MaterialAidObligation&o){validate_obligation_impl(x,o,ObligationReadUse::original_budget_evidence);}
